mapper.select:
SELECT *
FROM tb_address_book
WHERE ADDRESS_ID = #{addressId}
AND USER_NO = #{userNo}

mapper.delete:
DELETE FROM tb_address_book
WHERE ADDRESS_ID = #{addressId}
AND USER_NO = #{userNo}

mapper.update:
UPDATE tb_address_book
SET IS_DEFAULT = 0
WHERE USER_NO = #{userNo}
AND ADDRESS_ID != #{addressId}

mapper.select:
SELECT COUNT(*)
FROM tb_address_book
WHERE USER_NO = #{userNo}
